// Starter file for Execution Context, Hoisting, and the `this` Keyword
// Task instructions:
// Create an object with methods that demonstrate all four `this` binding rules. Show the lost `this` problem and fix it with `bind`, `call`, and `apply`...

solution_code:
const person = {
  name: "Alice",
  greet() {
    console.log(`Hello, ${this.name}`);  // "this" = person
  }
};
person.greet(); // "Hello, Alice"

// Losing this
const greetFn = person.greet;
greetFn(); // "Hello, undefined" (or error in strict mode)

// Fix with bind
const boundGreet = person.greet.bind(person);
boundGreet(); // "Hello, Alice"

// Arrow function inherits this
const team = {
  name: "Dev",
  members: ["Alice", "Bob"],
  listMembers() {
    this.members.forEach(member => {
      console.log(`${member} is on ${this.name}`);  // "this" = team
    });
  }
};

// Hoisting demonstration
console.log(x);  // undefined (var hoisted)
var x = 5;
console.log(x);  // 5

// console.log(y); // ReferenceError: Cannot access 'y' before initialization
let y = 10;

hoistedFn(); // Works — function declaration hoisted
function hoistedFn() { console.log("Hoisted!"); }

// notHoisted(); // TypeError: notHoisted is not a function
const notHoisted = () => console.log("Not hoisted");
